public void solve(char[][] board) {
    if (board == null || board.length == 0 || board[0].length == 0) {
        return;
    }
    int rows = board.length, cols = board[0].length;
    Queue<int[]> q = new LinkedList<>();
    // Seed: enqueue + mark every border 'O'.
    for (int r = 0; r < rows; r++) {
        enqueueIfO(board, r, 0, q);
        enqueueIfO(board, r, cols - 1, q);
    }
    for (int c = 0; c < cols; c++) {
        enqueueIfO(board, 0, c, q);
        enqueueIfO(board, rows - 1, c, q);
    }
    int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
    while (!q.isEmpty()) {
        int[] cell = q.poll();
        for (int[] d : dirs) {
            enqueueIfO(board, cell[0] + d[0], cell[1] + d[1], q);
        }
    }
    for (int r = 0; r < rows; r++) {
        for (int c = 0; c < cols; c++) {
            if (board[r][c] == 'O') {
                board[r][c] = 'X';
            } else if (board[r][c] == '#') {
                board[r][c] = 'O';
            }
        }
    }
}

private void enqueueIfO(char[][] board, int r, int c, Queue<int[]> q) {
    if (r < 0 || r >= board.length || c < 0 || c >= board[0].length
            || board[r][c] != 'O') {
        return;
    }
    board[r][c] = '#'; // mark on enqueue
    q.offer(new int[]{r, c});
}

