from collections import deque

def solve(self, board: list[list[str]]) -> None:
    if not board or not board[0]:
        return
    rows, cols = len(board), len(board[0])
    q = deque()

    def enqueue_if_o(r: int, c: int) -> None:
        if 0 <= r < rows and 0 <= c < cols and board[r][c] == 'O':
            board[r][c] = '#'  # mark on enqueue
            q.append((r, c))

    # Seed: enqueue + mark every border 'O'.
    for r in range(rows):
        enqueue_if_o(r, 0)
        enqueue_if_o(r, cols - 1)
    for c in range(cols):
        enqueue_if_o(0, c)
        enqueue_if_o(rows - 1, c)

    dirs = [(1, 0), (-1, 0), (0, 1), (0, -1)]
    while q:
        cr, cc = q.popleft()
        for dr, dc in dirs:
            enqueue_if_o(cr + dr, cc + dc)

    for r in range(rows):
        for c in range(cols):
            if board[r][c] == 'O':
                board[r][c] = 'X'
            elif board[r][c] == '#':
                board[r][c] = 'O'

