public void solve(char[][] board) {
    if (board == null || board.length == 0 || board[0].length == 0) {
        return;
    }
    int rows = board.length, cols = board[0].length;
    int virtual = rows * cols;
    int[] parent = new int[rows * cols + 1];
    for (int i = 0; i <= virtual; i++) {
        parent[i] = i;
    }
    for (int r = 0; r < rows; r++) {
        for (int c = 0; c < cols; c++) {
            if (board[r][c] != 'O') {
                continue;
            }
            int id = r * cols + c;
            if (r == 0 || r == rows - 1 || c == 0 || c == cols - 1) {
                union(parent, id, virtual);
            }
            if (r + 1 < rows && board[r + 1][c] == 'O') {
                union(parent, id, (r + 1) * cols + c);
            }
            if (c + 1 < cols && board[r][c + 1] == 'O') {
                union(parent, id, r * cols + (c + 1));
            }
        }
    }
    for (int r = 0; r < rows; r++) {
        for (int c = 0; c < cols; c++) {
            if (board[r][c] == 'O'
                    && find(parent, r * cols + c) != find(parent, virtual)) {
                board[r][c] = 'X';
            }
        }
    }
}

private int find(int[] parent, int x) {
    while (parent[x] != x) {
        parent[x] = parent[parent[x]]; // path compression
        x = parent[x];
    }
    return x;
}

private void union(int[] parent, int a, int b) {
    parent[find(parent, a)] = find(parent, b);
}

