        return
    rows, cols = len(board), len(board[0])
    virtual = rows * cols
    parent = list(range(rows * cols + 1))

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]  # path compression
            x = parent[x]
        return x

    def union(a: int, b: int) -> None:
        parent[find(a)] = find(b)

    for r in range(rows):
        for c in range(cols):
            if board[r][c] != 'O':
                continue
            idx = r * cols + c
            if r == 0 or r == rows - 1 or c == 0 or c == cols - 1:
                union(idx, virtual)
            if r + 1 < rows and board[r + 1][c] == 'O':
                union(idx, (r + 1) * cols + c)
            if c + 1 < cols and board[r][c + 1] == 'O':
                union(idx, r * cols + (c + 1))

    for r in range(rows):
        for c in range(cols):
            if board[r][c] == 'O' and find(r * cols + c) != find(virtual):
                board[r][c] = 'X'

